import React from "react";
import { FaShieldAlt } from "react-icons/fa";

// فرم عمومیِ افزودن/ویرایش موجودیت‌هایی که فقط یک «نام» می‌گیرند
// (مثل برند دستگاه، نوع دستگاه، تخصص و ...)
//
// props:
//   title: عنوان بالای فرم، مثلاً "افزودن برند دستگاه" یا "ویرایش نوع دستگاه"
//   fieldLabel: پلیس‌هولدر/برچسب فیلد ورودی (پیش‌فرض "نام")
//   icon: آیکون سمت راست فیلد (پیش‌فرض FaShieldAlt)
//   initialValue: مقدار اولیه (برای حالت ویرایش)
//   submitLabel: متن دکمه (پیش‌فرض "ثبت")
//   onSubmit(value): وقتی فرم ساب‌میت می‌شود صدا زده می‌شود
class NameEntityForm extends React.Component {
  constructor(props) {
    super(props);
    this.state = { name: props.initialValue || "" };
    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
  }

  handleChange(e) {
    this.setState({ name: e.target.value });
  }

  handleSubmit(e) {
    e.preventDefault();
    const { onSubmit } = this.props;
    const { name } = this.state;

    // TODO: اینجا باید به API واقعی (ایجاد یا ویرایش) وصل بشه
    // مثال:
    // if (this.props.entityId) {
    //   await api.updateEntity(this.props.entityId, { name });
    // } else {
    //   await api.createEntity({ name });
    // }

    if (onSubmit) {
      onSubmit(name);
    } else {
      console.log("ثبت مقدار:", name);
    }
  }

  render() {
    const {
      title = "افزودن مورد جدید",
      fieldLabel = "نام",
      icon,
      submitLabel = "ثبت",
    } = this.props;
    const { name } = this.state;

    return (
      <div>
        <div className="container-fluid px-3 pt-5 pb-5" style={{ maxWidth: 480 }}>
          <h1 className="fs-6 fw-semibold text-dark text-center mb-4">{title}</h1>

          <form onSubmit={this.handleSubmit}>
            <div className="d-flex align-items-center justify-content-between gap-2 border rounded-3 px-3 py-3 mb-4 bg-white">
              <input
                type="text"
                placeholder={fieldLabel}
                value={name}
                onChange={this.handleChange}
                className="form-control border-0 shadow-none text-end p-0"
              />
              {icon || <FaShieldAlt className="text-secondary" size={18} />}
            </div>

            <button
              type="submit"
              className="btn btn-primary w-100 rounded-3 py-3"
              style={{ transition: "opacity 0.15s ease" }}
            >
              {submitLabel}
            </button>
          </form>
        </div>
      </div>
    );
  }
}

export default NameEntityForm;
